// ===== UPLOAD MEDIAS (Google Drive) =====
// Remplacer par le Client ID OAuth créé dans Google Cloud Console (APIs & Services >
// Identifiants > ID client OAuth > type "Application Web"), avec comme origine
// JavaScript autorisée l'adresse où tourne Compo. L'API Google Drive doit être
// activée dans le même projet Cloud.
var GOOGLE_DRIVE_CLIENT_ID = '467937011181-u326c0hh2oo61o9mish06q3oqf44kj8r.apps.googleusercontent.com';
var GOOGLE_DRIVE_SCOPE = 'https://www.googleapis.com/auth/drive.file';
var _uploadGoogleToken = null; // {access_token, expires_at}
var _uploadTokenClient = null;
var _uploadFichiers = [];
var _uploadSujetsCache = [];

function osUploadTokenValide(){
  return !!(_uploadGoogleToken && _uploadGoogleToken.expires_at > Date.now() + 60000);
}

function _osUploadChargerGSI(callback){
  if(window.google && google.accounts && google.accounts.oauth2){ callback(); return; }
  var existing = document.getElementById('gsi-client-script');
  if(existing){ existing.addEventListener('load', callback); return; }
  var s = document.createElement('script');
  s.id = 'gsi-client-script';
  s.src = 'https://accounts.google.com/gsi/client';
  s.onload = callback;
  s.onerror = function(){ notif('Impossible de charger Google Identity Services','erreur'); };
  document.head.appendChild(s);
}

function osUploadSeConnecter(){
  _osUploadChargerGSI(function(){
    if(!window.google || !google.accounts || !google.accounts.oauth2){ notif('Impossible de charger Google Identity Services','erreur'); return; }
    if(!_uploadTokenClient){
      _uploadTokenClient = google.accounts.oauth2.initTokenClient({
        client_id: GOOGLE_DRIVE_CLIENT_ID,
        scope: GOOGLE_DRIVE_SCOPE,
        callback: function(resp){
          if(resp.error){ notif('Connexion Google refusée','erreur'); return; }
          _uploadGoogleToken = { access_token: resp.access_token, expires_at: Date.now() + ((resp.expires_in||3600)*1000) };
          // Rafraîchit l'appli réellement ouverte — Fichiers et Enregistrer partagent ce
          // même mécanisme de connexion mais sont deux fenêtres séparées ; chaque fonction
          // se protège elle-même si son propre conteneur n'existe pas (fenêtre fermée).
          osUploadMediasRender();
          osMagnetoRender();
        }
      });
    }
    _uploadTokenClient.requestAccessToken({ prompt: _uploadGoogleToken ? '' : 'consent' });
  });
}

function osUploadSeDeconnecter(){
  if(_uploadGoogleToken && window.google && google.accounts && google.accounts.oauth2){
    google.accounts.oauth2.revoke(_uploadGoogleToken.access_token, function(){});
  }
  _uploadGoogleToken = null;
  osUploadMediasRender();
}

function osUploadMediasRender(){
  var wc = document.getElementById('wincontent-upload-medias');
  if(!wc) return;
  wc.style.cssText = 'display:flex;flex-direction:column;height:100%;overflow:hidden;';
  // Communiqués/Images-articles : lus via le compte de service, consultables sans
  // compte Google. Rédactions (rushs + enregistrements) : privés, connexion Google
  // personnelle nécessaire pour voir/gérer ses propres fichiers.
  _osUploadEcranPrincipal(wc);
}

var UPLOAD_TYPE_ICONS = {video:'🎬', image:'🖼️', document:'📄', audio:'🎙️', autre:'📦'};

function _uploadTypeDeFichier(mime){
  mime = mime || '';
  if(mime.indexOf('video/') === 0) return 'video';
  if(mime.indexOf('image/') === 0) return 'image';
  if(mime.indexOf('audio/') === 0) return 'audio';
  if(mime === 'application/pdf' || mime.indexOf('document') !== -1 || mime.indexOf('msword') !== -1 || mime.indexOf('officedocument') !== -1) return 'document';
  return 'autre';
}

